class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size(), w = n - k, total = 0, mid = 0;
        for (int x : cardPoints) total += x;
        for (int r = 0; r < w; r++) mid += cardPoints[r];
        int least = mid;
        for (int r = w; r < n; r++) {
            int l = r - w + 1;
            mid += cardPoints[r] - cardPoints[l - 1];
            least = min(least, mid);
        }
        return total - least;
    }
};
